// Some portions generated by Claude
package org.eclipse.rdf4j.spin.function.spif;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class CastTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final IRI VOLATILE_TARGET = VF.createIRI("urn:test:spif-cast:volatile");

	private final AtomicInteger volatileInvocations = new AtomicInteger();

	private final Function volatileTarget = new Function() {

		@Override
		public String getURI() {
			return VOLATILE_TARGET.stringValue();
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) {
			return valueFactory.createLiteral(volatileInvocations.incrementAndGet());
		}

		@Override
		public boolean mustReturnDifferentResult() {
			return true;
		}
	};

	@BeforeEach
	void registerVolatileTarget() {
		FunctionRegistry.getInstance().add(volatileTarget);
	}

	@AfterEach
	void unregisterVolatileTarget() {
		FunctionRegistry.getInstance().remove(volatileTarget);
	}

	@Test
	void castIsRepeatable() {
		assertThat(new Cast().mustReturnDifferentResult()).isFalse();
	}

	@Test
	void datatypeConstructorIsStillUsed() {
		// only the registered xsd:integer constructor truncates; relabelling would yield "1.5"^^xsd:integer
		Value result = new Cast().evaluate(VF, VF.createLiteral(1.5d), XSD.INTEGER);

		assertThat(result).isEqualTo(VF.createLiteral("1", XSD.INTEGER));
	}

	@Test
	void volatileFunctionRegisteredUnderTargetIriIsNotInvoked() {
		Value result = new Cast().evaluate(VF, VF.createLiteral("5"), VOLATILE_TARGET);

		assertThat(result).isEqualTo(VF.createLiteral("5", VOLATILE_TARGET));
		assertThat(volatileInvocations).hasValue(0);
	}
}
